script:
const mount = root_element.querySelector('.ury-waiter-chart');
const empty = root_element.querySelector('.ury-waiter-empty');
let chart = null;
let timer = null;

function show_empty(message) {
	empty.textContent = message;
	empty.style.display = '';
	mount.style.display = 'none';
}

function render(data) {
	const datasets = (data.datasets || []).filter(function (d) {
		return d.values.some(function (v) { return v; });
	});
	if (!datasets.length) {
		show_empty(__('No sales in the last 7 days'));
		return;
	}
	empty.style.display = 'none';
	mount.style.display = '';
	const args = {
		type: 'bar',
		height: 300,
		colors: frappe.utils.get_chart_palette(),
		data: {
			labels: data.labels,
			datasets: datasets.map(function (d) { return { name: d.name, values: d.values }; })
		},
		axisOptions: { xIsSeries: 1 },
		barOptions: { spaceRatio: 0.4 },
		tooltipOptions: { formatTooltipY: function (v) { return format_currency(v); } }
	};
	if (chart) {
		chart.update(args.data);
	} else {
		chart = new frappe.Chart(mount, args);
	}
}

function load() {
	if (!root_element.host || !root_element.host.isConnected) {
		clearInterval(timer);
		return;
	}
	frappe.xcall('ury.ury.api.cashier_dashboard.get_waiter_sales_chart').then(render).catch(function () {
		show_empty(__('Sales by waiter is not available'));
	});
}

load();
timer = setInterval(load, 60000);
